            kad(1 + ia + 6*id) = kad(1 + ia + 6*id) &
                                    - kfac*sc*dbc(1 + ib + 6*ic)
            kbc(1 + ib + 6*ic) = kbc(1 + ib + 6*ic) &
                                    - kfac*sc*dad(1 + ia + 6*id)
