               jab(1 + ia + 6*ib) = 0.0_dp
            end do
         end do
         do id = 0, 2
            do gi = 1, 1
               ic = rc4(gi)
               dcd(1 + ic + 6*id) = dmat(idens, lamk + ic, sigl + id)
               jcd(1 + ic + 6*id) = 0.0_dp
            end do
         end do
         do gi = 1, 1
            ic = rc4(gi)
            do ia = 0, 5
               dac(1 + ia + 6*ic) = dmat(idens, mui + ia, lamk + ic)
               kac(1 + ia + 6*ic) = 0.0_dp
            end do
         end do
         do id = 0, 2
            do ia = 0, 5
               dad(1 + ia + 6*id) = dmat(idens, mui + ia, sigl + id)
               kad(1 + ia + 6*id) = 0.0_dp
            end do
